
begin;

create table if not exists public.accounting_accounts(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id),parent_id bigint references public.accounting_accounts(id),code text not null,name_en text not null,name_ar text not null,account_type text not null check(account_type in('asset','liability','equity','revenue','expense')),normal_balance text not null check(normal_balance in('debit','credit')),system_key text,is_postable boolean not null default true,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(clinic_id,code),unique(clinic_id,system_key));
create table if not exists public.accounting_fiscal_years(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id),name text not null,starts_on date not null,ends_on date not null,is_closed boolean not null default false,unique(clinic_id,name));
create table if not exists public.accounting_cost_centers(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id),branch_id bigint references public.branches(id),code text not null,name_en text not null,name_ar text not null,is_active boolean not null default true,unique(clinic_id,code));
create table if not exists public.accounting_journal_entries(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id),branch_id bigint references public.branches(id),fiscal_year_id bigint references public.accounting_fiscal_years(id),entry_number text not null,entry_date date not null,description_en text not null default '',description_ar text not null default '',status text not null default 'draft' check(status in('draft','posted','reversed')),source_type text,source_id bigint,posted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(clinic_id,entry_number));
create table if not exists public.accounting_journal_lines(id bigint generated by default as identity primary key,entry_id bigint not null references public.accounting_journal_entries(id) on delete cascade,clinic_id bigint not null references public.clinics(id),account_id bigint not null references public.accounting_accounts(id),cost_center_id bigint references public.accounting_cost_centers(id),customer_id bigint references public.customers(id),staff_id bigint references public.staff(id),debit numeric(14,2) not null default 0,credit numeric(14,2) not null default 0,memo_en text,memo_ar text,created_at timestamptz not null default now(),check(debit>=0 and credit>=0 and ((debit>0 and credit=0) or (credit>0 and debit=0))));
create table if not exists public.employee_financial_transactions(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id),branch_id bigint not null references public.branches(id),staff_id bigint not null references public.staff(id),transaction_type text not null check(transaction_type in('custody','advance','loan','expense_claim')),reference_number text not null,issued_on date not null default current_date,due_on date,amount numeric(14,2) not null check(amount>0),settled_amount numeric(14,2) not null default 0,outstanding_amount numeric(14,2) not null default 0,status text not null default 'open',purpose_en text not null default '',purpose_ar text not null default '',funding_method text not null default 'cash',journal_entry_id bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(clinic_id,reference_number));
create table if not exists public.employee_financial_settlements(id bigint generated by default as identity primary key,clinic_id bigint,transaction_id bigint,settlement_date date not null default current_date,amount numeric(14,2) not null default 0,settlement_method text not null default 'cash',notes_en text,notes_ar text,journal_entry_id bigint,created_at timestamptz not null default now());
alter table public.employee_financial_settlements add column if not exists settlement_method text not null default 'cash',add column if not exists notes_en text,add column if not exists notes_ar text,add column if not exists journal_entry_id bigint;

create or replace function public.accounting_validate_entry() returns trigger language plpgsql security definer set search_path=public as $$ declare d numeric;c numeric;s text;begin select status into s from accounting_journal_entries where id=coalesce(new.entry_id,old.entry_id);if s='posted' then select coalesce(sum(debit),0),coalesce(sum(credit),0) into d,c from accounting_journal_lines where entry_id=coalesce(new.entry_id,old.entry_id);if abs(d-c)>.005 then raise exception 'Journal entry is not balanced';end if;end if;return null;end$$;
drop trigger if exists accounting_entry_balance on public.accounting_journal_lines;create constraint trigger accounting_entry_balance after insert or update or delete on public.accounting_journal_lines deferrable initially deferred for each row execute function public.accounting_validate_entry();
create or replace function public.accounting_post_entry(p_entry_id bigint) returns void language plpgsql security definer set search_path=public as $$declare d numeric;c numeric;begin select coalesce(sum(debit),0),coalesce(sum(credit),0) into d,c from accounting_journal_lines where entry_id=p_entry_id;if d<=0 or abs(d-c)>.005 then raise exception 'Journal entry must be balanced';end if;update accounting_journal_entries set status='posted',posted_at=now() where id=p_entry_id and clinic_id=current_clinic_id();end$$;

do $$declare c record;p bigint;begin for c in select id from clinics loop insert into accounting_fiscal_years(clinic_id,name,starts_on,ends_on) values(c.id,extract(year from current_date)::text,date_trunc('year',current_date)::date,(date_trunc('year',current_date)+interval '1 year'-interval '1 day')::date) on conflict do nothing;insert into accounting_accounts(clinic_id,code,name_en,name_ar,account_type,normal_balance,is_postable) values(c.id,'1000','Assets','الأصول','asset','debit',false),(c.id,'2000','Liabilities','الالتزامات','liability','credit',false),(c.id,'3000','Equity','حقوق الملكية','equity','credit',false),(c.id,'4000','Revenue','الإيرادات','revenue','credit',false),(c.id,'5000','Expenses','المصروفات','expense','debit',false) on conflict do nothing;
select id into p from accounting_accounts where clinic_id=c.id and code='1000';insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values(c.id,p,'1110','Cash','النقدية','asset','debit','cash'),(c.id,p,'1120','Bank','البنك','asset','debit','bank'),(c.id,p,'1200','Accounts receivable','الذمم المدينة','asset','debit','accounts_receivable'),(c.id,p,'1300','Employee custodies','عهد الموظفين','asset','debit','employee_custody'),(c.id,p,'1310','Employee advances','سلف الموظفين','asset','debit','employee_advance'),(c.id,p,'1400','Inventory','المخزون','asset','debit','inventory') on conflict do nothing;
select id into p from accounting_accounts where clinic_id=c.id and code='2000';insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values(c.id,p,'2100','Accounts payable','الذمم الدائنة','liability','credit','accounts_payable'),(c.id,p,'2200','VAT payable','ضريبة القيمة المضافة','liability','credit','vat_payable'),(c.id,p,'2400','Employee deductions','استقطاعات الموظفين','liability','credit','employee_deductions') on conflict do nothing;
select id into p from accounting_accounts where clinic_id=c.id and code='3000';insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values(c.id,p,'3100','Capital','رأس المال','equity','credit','capital'),(c.id,p,'3200','Retained earnings','الأرباح المبقاة','equity','credit','retained_earnings') on conflict do nothing;
select id into p from accounting_accounts where clinic_id=c.id and code='4000';insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values(c.id,p,'4100','Clinical revenue','إيرادات الخدمات','revenue','credit','service_revenue'),(c.id,p,'4110','Sales discounts','خصومات المبيعات','revenue','debit','sales_discounts') on conflict do nothing;
select id into p from accounting_accounts where clinic_id=c.id and code='5000';insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values(c.id,p,'5100','Cost of services','تكلفة الخدمات','expense','debit','cost_of_services'),(c.id,p,'5200','Medical materials','المواد الطبية','expense','debit','medical_materials'),(c.id,p,'5300','Salaries','الرواتب','expense','debit','salaries'),(c.id,p,'5400','Rent','الإيجار','expense','debit','rent'),(c.id,p,'5500','Marketing','التسويق','expense','debit','marketing'),(c.id,p,'5600','Utilities','المرافق','expense','debit','utilities'),(c.id,p,'5800','Administrative expenses','المصروفات الإدارية','expense','debit','administrative'),(c.id,p,'5900','Other expenses','مصروفات أخرى','expense','debit','other_expense') on conflict do nothing;end loop;end$$;

create or replace function public.accounting_trial_balance(p_from date,p_to date) returns table(account_id bigint,code text,name_en text,name_ar text,account_type text,opening_debit numeric,opening_credit numeric,period_debit numeric,period_credit numeric,closing_debit numeric,closing_credit numeric) language sql security definer set search_path=public stable as $$with x as(select a.id,a.code,a.name_en,a.name_ar,a.account_type,a.normal_balance,coalesce(sum(l.debit)filter(where e.entry_date<p_from and e.status='posted'),0)od,coalesce(sum(l.credit)filter(where e.entry_date<p_from and e.status='posted'),0)oc,coalesce(sum(l.debit)filter(where e.entry_date between p_from and p_to and e.status='posted'),0)pd,coalesce(sum(l.credit)filter(where e.entry_date between p_from and p_to and e.status='posted'),0)pc from accounting_accounts a left join accounting_journal_lines l on l.account_id=a.id left join accounting_journal_entries e on e.id=l.entry_id where a.clinic_id=current_clinic_id() and a.is_postable group by a.id)select id,code,name_en,name_ar,account_type,greatest(od-oc,0),greatest(oc-od,0),pd,pc,greatest(od+pd-oc-pc,0),greatest(oc+pc-od-pd,0)from x where od<>0 or oc<>0 or pd<>0 or pc<>0 order by code$$;
create or replace function public.accounting_financial_statements(p_from date,p_to date) returns jsonb language sql security definer set search_path=public stable as $$with b as(select a.account_type,a.code,a.name_en,a.name_ar,case when a.normal_balance='debit'then coalesce(sum(l.debit-l.credit),0)else coalesce(sum(l.credit-l.debit),0)end amount from accounting_accounts a left join accounting_journal_lines l on l.account_id=a.id left join accounting_journal_entries e on e.id=l.entry_id and e.status='posted' and e.entry_date<=p_to where a.clinic_id=current_clinic_id() and a.is_postable group by a.id),r as(select * from b where account_type in('revenue','expense'))select jsonb_build_object('balanceSheet',jsonb_build_object('assets',coalesce((select jsonb_agg(to_jsonb(b))from b where account_type='asset'and amount<>0),'[]'),'liabilities',coalesce((select jsonb_agg(to_jsonb(b))from b where account_type='liability'and amount<>0),'[]'),'equity',coalesce((select jsonb_agg(to_jsonb(b))from b where account_type='equity'and amount<>0),'[]')),'incomeStatement',jsonb_build_object('revenue',coalesce((select jsonb_agg(to_jsonb(r))from r where account_type='revenue'and amount<>0),'[]'),'expenses',coalesce((select jsonb_agg(to_jsonb(r))from r where account_type='expense'and amount<>0),'[]')))$$;

do $$declare t text;begin foreach t in array array['accounting_accounts','accounting_fiscal_years','accounting_cost_centers','accounting_journal_entries','accounting_journal_lines','employee_financial_transactions','employee_financial_settlements']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists %I on public.%I',t||'_staff_scope',t);execute format('create policy %I on public.%I for all to authenticated using(clinic_id=public.current_clinic_id()) with check(clinic_id=public.current_clinic_id())',t||'_staff_scope',t);execute format('grant select,insert,update,delete on public.%I to authenticated',t);end loop;end$$;
grant usage,select on all sequences in schema public to authenticated;grant execute on function public.accounting_trial_balance(date,date)to authenticated;grant execute on function public.accounting_financial_statements(date,date)to authenticated;grant execute on function public.accounting_post_entry(bigint)to authenticated;
-- Repair Arabic labels if an earlier draft was partially applied.
update public.accounting_accounts a set name_ar=v.name_ar from(values
('1000','الأصول'),('2000','الالتزامات'),('3000','حقوق الملكية'),('4000','الإيرادات'),('5000','المصروفات'),('1110','النقدية'),('1120','البنك'),('1200','الذمم المدينة'),('1300','عهد الموظفين'),('1310','سلف الموظفين'),('1400','المخزون'),('2100','الذمم الدائنة'),('2200','ضريبة القيمة المضافة'),('2400','استقطاعات الموظفين'),('3100','رأس المال'),('3200','الأرباح المبقاة'),('4100','إيرادات الخدمات'),('4110','خصومات المبيعات'),('5100','تكلفة الخدمات'),('5200','المواد الطبية'),('5300','الرواتب'),('5400','الإيجار'),('5500','التسويق'),('5600','المرافق'),('5800','المصروفات الإدارية'),('5900','مصروفات أخرى'))v(code,name_ar) where a.code=v.code;

-- Add the remaining standard accounts (29 postable accounts per clinic).
do $$declare c record;p bigint;begin for c in select id from public.clinics loop
select id into p from accounting_accounts where clinic_id=c.id and code='1000';
insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values
(c.id,p,'1130','Payment gateway clearing','تسويات بوابة الدفع','asset','debit','gateway_clearing'),(c.id,p,'1500','Prepaid expenses','المصروفات المقدمة','asset','debit','prepaid_expenses'),(c.id,p,'1600','Fixed assets','الأصول الثابتة','asset','debit','fixed_assets'),(c.id,p,'1690','Accumulated depreciation','مجمع الإهلاك','asset','credit','accumulated_depreciation') on conflict do nothing;
select id into p from accounting_accounts where clinic_id=c.id and code='2000';insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values(c.id,p,'2300','Accrued expenses','المصروفات المستحقة','liability','credit','accrued_expenses') on conflict do nothing;
select id into p from accounting_accounts where clinic_id=c.id and code='4000';insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values(c.id,p,'4200','Consultation revenue','إيرادات الاستشارات','revenue','credit','consultation_revenue'),(c.id,p,'4900','Other revenue','إيرادات أخرى','revenue','credit','other_revenue') on conflict do nothing;
select id into p from accounting_accounts where clinic_id=c.id and code='5000';insert into accounting_accounts(clinic_id,parent_id,code,name_en,name_ar,account_type,normal_balance,system_key) values(c.id,p,'5700','Depreciation','الإهلاك','expense','debit','depreciation') on conflict do nothing;end loop;end$$;

create or replace function public.accounting_account_id(p_clinic bigint,p_key text) returns bigint language sql stable security definer set search_path=public as $$select id from accounting_accounts where clinic_id=p_clinic and system_key=p_key and is_active limit 1$$;

create or replace function public.accounting_payment_post() returns trigger language plpgsql security definer set search_path=public as $$
declare j jsonb:=to_jsonb(new);eid bigint;cash_id bigint;ar_id bigint;revenue_id bigint;vat_id bigint;discount_id bigint;paid numeric:=coalesce(nullif(j->>'paid_amount','')::numeric,nullif(j->>'amount','')::numeric,0);subtotal numeric:=coalesce(nullif(j->>'subtotal_amount','')::numeric,greatest(coalesce(nullif(j->>'amount','')::numeric,0)-coalesce(nullif(j->>'tax_amount','')::numeric,0),0));tax numeric:=coalesce(nullif(j->>'tax_amount','')::numeric,0);discount numeric:=coalesce(nullif(j->>'discount_amount','')::numeric,0);total numeric;balance numeric;
begin total:=greatest(subtotal-discount+tax,0);balance:=greatest(total-paid,0);delete from accounting_journal_entries where clinic_id=new.clinic_id and source_type='payment' and source_id=new.id;if total=0 then return new;end if;
cash_id:=accounting_account_id(new.clinic_id,case when lower(coalesce(j->>'payment_method','cash')) in('cash','نقدا','نقداً') then 'cash' else 'bank' end);ar_id:=accounting_account_id(new.clinic_id,'accounts_receivable');revenue_id:=accounting_account_id(new.clinic_id,'service_revenue');vat_id:=accounting_account_id(new.clinic_id,'vat_payable');discount_id:=accounting_account_id(new.clinic_id,'sales_discounts');
insert into accounting_journal_entries(clinic_id,branch_id,entry_number,entry_date,description_en,description_ar,status,source_type,source_id)values(new.clinic_id,new.branch_id,'PAY-'||new.id,coalesce(nullif(j->>'payment_date','')::timestamptz::date,current_date),'Patient invoice','فاتورة مريض','draft','payment',new.id)returning id into eid;
if paid>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,debit,credit)values(eid,new.clinic_id,cash_id,new.customer_id,least(paid,total),0);end if;if balance>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,debit,credit)values(eid,new.clinic_id,ar_id,new.customer_id,balance,0);end if;if discount>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,debit,credit)values(eid,new.clinic_id,discount_id,new.customer_id,discount,0);end if;if subtotal>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,debit,credit)values(eid,new.clinic_id,revenue_id,new.customer_id,0,subtotal);end if;if tax>0 then insert into accounting_journal_lines(entry_id,clinic_id,account_id,customer_id,debit,credit)values(eid,new.clinic_id,vat_id,new.customer_id,0,tax);end if;update accounting_journal_entries set status='posted',posted_at=now()where id=eid;return new;end$$;
drop trigger if exists payments_accounting_post on public.payments;create trigger payments_accounting_post after insert or update on public.payments for each row execute function public.accounting_payment_post();

create or replace function public.accounting_employee_finance_post() returns trigger language plpgsql security definer set search_path=public as $$declare eid bigint;debit_id bigint;credit_id bigint;begin new.outstanding_amount:=greatest(new.amount-coalesce(new.settled_amount,0),0);new.status:=case when new.outstanding_amount=0 then 'settled' when coalesce(new.settled_amount,0)>0 then 'partial' else 'open' end;delete from accounting_journal_entries where clinic_id=new.clinic_id and source_type='employee_finance' and source_id=new.id;debit_id:=accounting_account_id(new.clinic_id,case when new.transaction_type='custody'then'employee_custody'when new.transaction_type in('advance','loan')then'employee_advance'else'administrative'end);credit_id:=accounting_account_id(new.clinic_id,case when lower(new.funding_method)='cash'then'cash'else'bank'end);insert into accounting_journal_entries(clinic_id,branch_id,entry_number,entry_date,description_en,description_ar,status,source_type,source_id)values(new.clinic_id,new.branch_id,'EMP-'||new.id,new.issued_on,'Employee financial transaction','حركة مالية لموظف','draft','employee_finance',new.id)returning id into eid;insert into accounting_journal_lines(entry_id,clinic_id,account_id,staff_id,debit,credit)values(eid,new.clinic_id,debit_id,new.staff_id,new.amount,0),(eid,new.clinic_id,credit_id,new.staff_id,0,new.amount);update accounting_journal_entries set status='posted',posted_at=now()where id=eid;new.journal_entry_id:=eid;return new;end$$;
drop trigger if exists employee_finance_accounting_post on public.employee_financial_transactions;create trigger employee_finance_accounting_post before insert or update on public.employee_financial_transactions for each row execute function public.accounting_employee_finance_post();

create or replace function public.accounting_employee_settlement_post() returns trigger language plpgsql security definer set search_path=public as $$declare tr record;eid bigint;debit_id bigint;credit_id bigint;settled numeric;begin select * into tr from employee_financial_transactions where id=new.transaction_id;if tr.id is null then raise exception 'Employee transaction not found';end if;new.clinic_id:=tr.clinic_id;delete from accounting_journal_entries where clinic_id=tr.clinic_id and source_type='employee_settlement' and source_id=new.id;debit_id:=accounting_account_id(tr.clinic_id,case when lower(new.settlement_method)='cash'then'cash'else'bank'end);credit_id:=accounting_account_id(tr.clinic_id,case when tr.transaction_type='custody'then'employee_custody'else'employee_advance'end);insert into accounting_journal_entries(clinic_id,branch_id,entry_number,entry_date,description_en,description_ar,status,source_type,source_id)values(tr.clinic_id,tr.branch_id,'SET-'||new.id,new.settlement_date,'Employee settlement','تسوية موظف','draft','employee_settlement',new.id)returning id into eid;insert into accounting_journal_lines(entry_id,clinic_id,account_id,staff_id,debit,credit)values(eid,tr.clinic_id,debit_id,tr.staff_id,new.amount,0),(eid,tr.clinic_id,credit_id,tr.staff_id,0,new.amount);update accounting_journal_entries set status='posted',posted_at=now()where id=eid;new.journal_entry_id:=eid;select coalesce(sum(amount),0)into settled from employee_financial_settlements where transaction_id=tr.id and id<>new.id;update employee_financial_transactions set settled_amount=settled+new.amount,outstanding_amount=greatest(amount-settled-new.amount,0),status=case when amount<=settled+new.amount then'settled'else'partial'end where id=tr.id;return new;end$$;
drop trigger if exists employee_settlement_accounting_post on public.employee_financial_settlements;create trigger employee_settlement_accounting_post before insert or update on public.employee_financial_settlements for each row execute function public.accounting_employee_settlement_post();

commit;
